package com.trampolim.api.career;
import java.util.*;import java.time.*;import java.math.*;
import static com.trampolim.api.radar.RadarModel.*;import com.trampolim.api.radar.*;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class CompanyCareerService {
 final JdbcTemplate jdbc;final RadarBridge bridge;
 public CompanyCareerService(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge){this.jdbc=jdbc;this.bridge=bridge;}
 public record Skill(String skillCode,int level){}public record Criterion(String key,String name,int weight){}
 public record Challenge(String title,String description,List<Skill> skills,List<Criterion> criteria,int passPercent,String materials,String materialUrl,String terms,Instant deadline,String status,int revision){}
 public record Delivery(int version,UUID receiptId,long challengeId,String alias,String body,String projectUrl,String requestHash,Instant consentAt){}
 public record Receipt(int version,UUID receiptId){}public record Review(UUID clientKey,Map<String,Integer> scores,String feedback){}
 public record Context(String regime,String regionCode,String schoolRequirements,String institution,String documentation,boolean firstExperience,boolean employerLegalConfirmation){}
 public long member(String email,boolean edit){var rows=jdbc.queryForList("SELECT m.company_id,m.role FROM company_members m JOIN company_users u ON u.id=m.user_id WHERE LOWER(u.email)=LOWER(?) AND u.email_verified=TRUE AND u.account_status='ACTIVE' ORDER BY m.company_id LIMIT 1",email);if(rows.isEmpty()||edit&&!Set.of("OWNER","ADMIN","RECRUITER").contains(rows.get(0).get("role")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Permissão empresarial insuficiente.");return ((Number)rows.get(0).get("company_id")).longValue();}
 public void ownChallenge(String email,long id,boolean edit){long company=member(email,edit);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM company_challenges WHERE id=? AND company_id=?)",Boolean.class,id,company)))throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
 void audit(long company,String email,String event){jdbc.update("INSERT INTO company_audit_events(company_id,actor_user_id,event_type) SELECT ?,id,? FROM company_users WHERE LOWER(email)=LOWER(?)",company,event,email);}
 private String select(){return "SELECT d.*,c.trade_name,c.public_slug FROM company_challenges d JOIN companies c ON c.id=d.company_id";}
 private Map<String,Object> decode(Map<String,Object> row){for(String field:List.of("skills","rubric"))row.put(field,bridge.convert(bridge.read(row.get(field)),Object.class));return row;}
 public Map<String,Object> publicChallenges(long before,int limit,String region){CareerRules.page(before,limit);String uf=CareerRules.region(region,true);var rows=jdbc.queryForList("SELECT d.id,d.title,d.description,d.deadline,c.trade_name,c.state FROM company_challenges d JOIN companies c ON c.id=d.company_id WHERE d.id<? AND d.status='PUBLISHED' AND d.deadline>CURRENT_TIMESTAMP AND c.verification_status='APPROVED' AND (?='' OR UPPER(c.state)=?) ORDER BY d.id DESC LIMIT ?",before,uf,uf,limit+1);return CareerRules.pageResult(rows,limit);}
 public Map<String,Object> publicChallenge(long id){return decode(jdbc.queryForList(select()+" WHERE d.id=? AND d.status='PUBLISHED' AND d.deadline>CURRENT_TIMESTAMP AND c.verification_status='APPROVED'",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Desafio não disponível.")));}
 public Map<String,Object> challenge(String email,long id){ownChallenge(email,id,false);return decode(jdbc.queryForMap(select()+" WHERE d.id=?",id));}
 public Map<String,Object> challenges(String email,long before,int limit){CareerRules.page(before,limit);return CareerRules.pageResult(jdbc.queryForList("SELECT id,title,status,deadline,revision FROM company_challenges WHERE company_id=? AND id<? ORDER BY id DESC LIMIT ?",member(email,false),before,limit+1),limit);}
 @Transactional("empresasTransactionManager")public Map<String,Object> save(String email,long id,Challenge input){long company=member(email,true);if(input==null||text(input.title(),180).isEmpty()||text(input.description(),5000).isEmpty()||text(input.terms(),3000).length()<20||input.deadline()==null||!Set.of("DRAFT","PUBLISHED","CLOSED").contains(Objects.toString(input.status(),""))||input.skills()==null||input.skills().isEmpty()||input.skills().size()>20||input.skills().stream().anyMatch(s->s==null||s.skillCode()==null||s.level()<1||s.level()>4)||input.skills().stream().map(Skill::skillCode).distinct().count()!=input.skills().size()||input.criteria()==null||input.criteria().isEmpty()||input.criteria().size()>10||input.passPercent()<1||input.passPercent()>100)bad("Revise título, competências, critérios, prazo e condições transparentes de participação.");var keys=new HashSet<String>();for(var c:input.criteria())if(c==null||!text(c.key(),40).matches("[a-z][a-z0-9-]{0,39}")||!keys.add(c.key())||text(c.name(),180).isEmpty()||c.weight()<1||c.weight()>100)bad("Critérios devem ter identificadores únicos e pesos de 1 a 100.");if(input.criteria().stream().mapToInt(Criterion::weight).sum()!=100)bad("Os pesos dos critérios devem somar 100.");bridge.validateSkills(input.skills().stream().map(Skill::skillCode).toList());String url=CareerRules.https(input.materialUrl());text(input.materials(),3000);jdbc.queryForObject("SELECT id FROM companies WHERE id=? FOR UPDATE",Long.class,company);if(input.status().equals("PUBLISHED")&&(!input.deadline().isAfter(Instant.now())||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT verification_status='APPROVED' FROM companies WHERE id=?",Boolean.class,company))))bad("A empresa deve estar aprovada e o prazo precisa estar aberto.");if(id>0){ownChallenge(email,id,true);jdbc.queryForObject("SELECT id FROM company_challenges WHERE id=? FOR UPDATE",Long.class,id);if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM company_challenge_submissions WHERE challenge_id=?)",Boolean.class,id))){var previous=jdbc.queryForMap("SELECT title,description,skills,rubric,materials,material_url,terms FROM company_challenges WHERE id=?",id);if(!previous.get("title").equals(input.title().trim())||!previous.get("description").equals(input.description().trim())||!bridge.read(previous.get("skills")).equals(bridge.read(bridge.encode(input.skills())))||!bridge.read(previous.get("rubric")).equals(bridge.read(bridge.encode(Map.of("criteria",input.criteria(),"passPercent",input.passPercent()))))||!previous.get("terms").equals(input.terms().trim())||!previous.get("materials").equals(text(input.materials(),3000))||!previous.get("material_url").equals(url))throw new ResponseStatusException(HttpStatus.CONFLICT,"Após receber entregas, preserve o conteúdo, os critérios e as condições. Crie outro desafio para alterá-los.");}}
  var rubric=Map.of("criteria",input.criteria(),"passPercent",input.passPercent());if(id==0){if(jdbc.queryForObject("SELECT count(*) FROM company_challenges WHERE company_id=? AND status<>'CLOSED'",Integer.class,company)>=100)bad("Encerre desafios antigos antes de criar outros.");id=jdbc.queryForObject("INSERT INTO company_challenges(company_id,title,description,skills,rubric,materials,material_url,terms,deadline,status) VALUES (?,?,?,?::jsonb,?::jsonb,?,?,?,?,?) RETURNING id",Long.class,company,input.title().trim(),input.description().trim(),bridge.encode(input.skills()),bridge.encode(rubric),text(input.materials(),3000),url,input.terms().trim(),java.sql.Timestamp.from(input.deadline()),input.status());}else if(jdbc.update("UPDATE company_challenges SET title=?,description=?,skills=?::jsonb,rubric=?::jsonb,materials=?,material_url=?,terms=?,deadline=?,status=?,revision=revision+1 WHERE id=? AND company_id=? AND revision=?",input.title().trim(),input.description().trim(),bridge.encode(input.skills()),bridge.encode(rubric),text(input.materials(),3000),url,input.terms().trim(),java.sql.Timestamp.from(input.deadline()),input.status(),id,company,input.revision())==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"O desafio mudou; reabra os dados.");audit(company,email,"CAREER_CHALLENGE_SAVED");return challenge(email,id);
 }
 @Transactional("empresasTransactionManager")public Map<String,Object> receive(String key,Delivery input){bridge.authorize(key);if(input==null||input.version()!=1||input.receiptId()==null||input.challengeId()<1||text(input.alias(),80).isEmpty()||text(input.body(),12000).length()<20||input.requestHash()==null||!input.requestHash().matches("[a-f0-9]{64}")||input.consentAt()==null||input.consentAt().isAfter(Instant.now().plusSeconds(60))||input.consentAt().isBefore(Instant.now().minusSeconds(90L*86400)))bad("Entrega inválida.");jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(rs,n)->0,input.receiptId().toString());if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM career_withdrawn_receipts WHERE receipt_id=?)",Boolean.class,input.receiptId())))return Map.of("status","WITHDRAWN");var prior=jdbc.queryForList("SELECT request_hash,status FROM company_challenge_submissions WHERE receipt_id=?",input.receiptId());if(!prior.isEmpty()){if(!prior.get(0).get("request_hash").equals(input.requestHash()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Recibo já utilizado.");return Map.of("status",prior.get(0).get("status"));}jdbc.queryForObject("SELECT id FROM company_challenges WHERE id=? FOR UPDATE",Long.class,input.challengeId());var challenge=publicChallenge(input.challengeId());jdbc.update("INSERT INTO company_challenge_submissions(receipt_id,challenge_id,alias,body,project_url,request_hash,rubric,consent_at) VALUES (?,?,?,?,?,?,?::jsonb,?)",input.receiptId(),input.challengeId(),input.alias().trim(),input.body().trim(),CareerRules.https(input.projectUrl()),input.requestHash(),bridge.encode(challenge.get("rubric")),java.sql.Timestamp.from(input.consentAt()));return Map.of("status","RECEIVED");}
 public Map<String,Object> receipt(String key,Receipt input){bridge.authorize(key);if(input==null||input.version()!=1||input.receiptId()==null)bad("Recibo inválido.");var rows=jdbc.queryForList("SELECT s.receipt_id,s.challenge_id,s.alias,s.status,r.id AS review_id,r.score_percent,r.feedback,r.scores,r.reviewed_at,r.revoked_at FROM company_challenge_submissions s LEFT JOIN company_challenge_reviews r ON r.receipt_id=s.receipt_id WHERE s.receipt_id=?",input.receiptId());if(rows.isEmpty())return Map.of("status","PENDING");var row=rows.get(0);if(row.get("scores")!=null)row.put("scores",bridge.convert(bridge.read(row.get("scores")),Map.class));if(row.get("status").equals("WITHDRAWN")){row.remove("alias");row.remove("feedback");row.remove("scores");row.remove("score_percent");}return row;}
 @Transactional("empresasTransactionManager")public Map<String,Object> withdraw(String key,Receipt input){bridge.authorize(key);if(input==null||input.version()!=1||input.receiptId()==null)bad("Recibo inválido.");jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(rs,n)->0,input.receiptId().toString());jdbc.update("INSERT INTO career_withdrawn_receipts(receipt_id) VALUES (?) ON CONFLICT DO NOTHING",input.receiptId());jdbc.update("UPDATE company_challenge_submissions SET status='WITHDRAWN',alias='',body='',project_url='',withdrawn_at=COALESCE(withdrawn_at,CURRENT_TIMESTAMP) WHERE receipt_id=?",input.receiptId());jdbc.update("UPDATE company_challenge_reviews SET feedback='',scores='{}',revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE receipt_id=?",input.receiptId());return Map.of("status","WITHDRAWN");}
 public Map<String,Object> submissions(String email,long id,UUID before,int limit){ownChallenge(email,id,true);if(limit<1||limit>50)bad("Use até cinquenta entregas por página.");String cursor=before==null?"":" AND (s.received_at,s.receipt_id)<(SELECT received_at,receipt_id FROM company_challenge_submissions WHERE receipt_id=? AND challenge_id=?)";var args=new ArrayList<Object>();args.add(id);if(before!=null){args.add(before);args.add(id);}args.add(limit+1);var rows=jdbc.queryForList("SELECT s.receipt_id,s.alias,s.body,s.project_url,s.rubric,s.received_at,s.status,r.score_percent,r.feedback,r.scores,r.revoked_at FROM company_challenge_submissions s LEFT JOIN company_challenge_reviews r ON r.receipt_id=s.receipt_id WHERE s.challenge_id=?"+cursor+" ORDER BY s.received_at DESC,s.receipt_id DESC LIMIT ?",args.toArray());for(var row:rows)for(String field:List.of("rubric","scores"))if(row.get(field)!=null)row.put(field,bridge.convert(bridge.read(row.get(field)),Object.class));var result=new LinkedHashMap<String,Object>();result.put("items",rows.stream().limit(limit).toList());result.put("nextCursor",rows.size()>limit?rows.get(limit-1).get("receipt_id"):null);return result;}
 @Transactional("empresasTransactionManager")public Map<String,Object> review(String email,long id,UUID receipt,Review input){ownChallenge(email,id,true);if(input==null||input.clientKey()==null||input.scores()==null||text(input.feedback(),3000).length()<10)bad("Informe notas por critério e feedback de ao menos dez caracteres.");var rows=jdbc.queryForList("SELECT rubric,status FROM company_challenge_submissions WHERE receipt_id=? AND challenge_id=? FOR UPDATE",receipt,id);if(rows.isEmpty()||rows.get(0).get("status").equals("WITHDRAWN"))throw new ResponseStatusException(HttpStatus.NOT_FOUND);var prior=jdbc.queryForList("SELECT id,scores,feedback,score_percent FROM company_challenge_reviews WHERE receipt_id=?",receipt);if(!prior.isEmpty()){var p=prior.get(0);if(!p.get("id").equals(input.clientKey())||!bridge.read(p.get("scores")).equals(bridge.read(bridge.encode(input.scores())))||!p.get("feedback").equals(input.feedback().trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"A avaliação já foi registrada e não pode ser substituída.");return Map.of("scorePercent",p.get("score_percent"));}var rubric=bridge.read(rows.get(0).get("rubric"));var expected=new HashSet<String>();int total=0;for(var criterion:rubric.path("criteria")){String c=criterion.path("key").asText();expected.add(c);Integer score=input.scores().get(c);if(score==null||score<0||score>100)bad("Notas de 0 a 100 em todos os critérios.");total+=score*criterion.path("weight").asInt();}if(!input.scores().keySet().equals(expected))bad("Os critérios devem corresponder à versão aceita pelo participante.");BigDecimal score=BigDecimal.valueOf(total).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);jdbc.update("INSERT INTO company_challenge_reviews(id,receipt_id,reviewer_id,scores,score_percent,feedback) SELECT ?,?,id,?::jsonb,?,? FROM company_users WHERE LOWER(email)=LOWER(?)",input.clientKey(),receipt,bridge.encode(input.scores()),score,input.feedback().trim(),email);jdbc.update("UPDATE company_challenge_submissions SET status='REVIEWED' WHERE receipt_id=?",receipt);audit(member(email,true),email,"CAREER_CHALLENGE_REVIEWED");return Map.of("scorePercent",score,"evidenceType","COMPANY_CHALLENGE_REVIEW","educationalCredential",false);}
 public Map<String,Object> context(String email,long listing){long company=member(email,false);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM company_listings WHERE id=? AND company_id=?)",Boolean.class,listing,company)))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return jdbc.queryForList("SELECT * FROM company_career_context WHERE listing_id=?",listing).stream().findFirst().orElse(Map.of());}
 public void context(String email,long listing,Context input){long company=member(email,true);if(input==null||!Set.of("EMPLOYMENT","INTERNSHIP","APPRENTICESHIP").contains(Objects.toString(input.regime(),"")))bad("Selecione emprego, estágio ou aprendizagem.");var rows=jdbc.queryForList("SELECT is_internship FROM company_listings WHERE id=? AND company_id=? AND kind='job'",listing,company);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(Boolean.TRUE.equals(rows.get(0).get("is_internship"))!=input.regime().equals("INTERNSHIP"))bad("Estágios devem usar o cadastro específico e seu pagamento; esta configuração não altera a cobrança.");String region=CareerRules.region(input.regionCode(),false);jdbc.update("INSERT INTO company_career_context(listing_id,regime,region_code,school_requirements,institution,documentation,first_experience,employer_legal_confirmation) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(listing_id) DO UPDATE SET regime=EXCLUDED.regime,region_code=EXCLUDED.region_code,school_requirements=EXCLUDED.school_requirements,institution=EXCLUDED.institution,documentation=EXCLUDED.documentation,first_experience=EXCLUDED.first_experience,employer_legal_confirmation=EXCLUDED.employer_legal_confirmation,updated_at=CURRENT_TIMESTAMP",listing,input.regime(),region,text(input.schoolRequirements(),1000),text(input.institution(),180),text(input.documentation(),2000),input.firstExperience(),input.employerLegalConfirmation());audit(company,email,"CAREER_REGIME_UPDATED");}
 public Map<String,Object> opportunities(String regime,String region,boolean first,long before,int limit){CareerRules.page(before,limit);String uf=CareerRules.region(region,true);if(!regime.isEmpty()&&!Set.of("EMPLOYMENT","INTERNSHIP","APPRENTICESHIP").contains(regime))bad("Regime inválido.");var rows=jdbc.queryForList("SELECT l.id,l.title,l.description,c.trade_name AS company_name,c.public_slug AS company_slug,l.location,l.modality,l.requirements,x.regime,x.school_requirements,x.institution,x.documentation,x.first_experience,x.region_code,x.employer_legal_confirmation FROM company_listings l JOIN companies c ON c.id=l.company_id JOIN company_career_context x ON x.listing_id=l.id WHERE "+com.trampolim.api.company.CompanyRadarController.PUBLIC_JOB_CONDITION+" AND l.id<? AND (?='' OR x.regime=?) AND (?='' OR x.region_code=?) AND (?=FALSE OR x.first_experience=TRUE) AND (x.regime<>'APPRENTICESHIP' OR x.employer_legal_confirmation=TRUE) ORDER BY l.id DESC LIMIT ?",before,regime,regime,uf,uf,first,limit+1);return CareerRules.pageResult(rows,limit);}
}
